style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.pinimg.com/736x/8d/e0/06/8de006d30b67e3a7536e351987df5754.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Optional: make content slightly transparent so the background shows */
  .container-main, .content, .section-content, .rbx-body {
    background-color: rgba(255, 255, 255, 0.85) !important;
  }
}
